const photoSlider=document.querySelector('.photo-slider');let heroFront=Number(document.querySelector('.stage').dataset.front||0),photoDrag=false;const cleanTitle=s=>s.replace(/^(占位作品|占位文章)[:：]/,'').replace(/^(Placeholder post|Placeholder)[:：]\s*/i,'');
function syncHero(){heroFront=Number(document.querySelector('.stage').dataset.front||0);photoSlider.setAttribute('aria-valuenow',String(heroFront));photoSlider.setAttribute('aria-valuetext',tr(...[['海岸纸卡 / 作品页','Coast card / Works'],['森林纸卡 / 文字页','Forest card / Writing'],['山间纸卡 / 探索页','Mountain card / Explore']][heroFront]));photoSlider.querySelectorAll('.photo-tick').forEach((e,i)=>e.classList.toggle('current',i===heroFront));document.querySelector('.works-total').textContent=String(content[lang].works.length).padStart(2,'0');document.querySelectorAll('[data-note-page]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.notePage===learningPage)));}
function chooseHero(i){i=Math.max(0,Math.min(2,i));if(index>=0){detail=null;window.selectPaper(i);}else window.setFrontPaper(i);syncHero();}
const heroObserver=new MutationObserver(syncHero);heroObserver.observe(document.querySelector('.stage'),{attributes:true,attributeFilter:['data-front']});new ResizeObserver(syncHero).observe(photoSlider);
function photoIndex(e){const r=photoSlider.getBoundingClientRect();if(photoSlider.getAttribute('aria-orientation')==='horizontal')return Math.round(Math.max(0,Math.min(1,(e.clientX-r.left-22)/(r.width-44)))*2);return Math.round(Math.max(0,Math.min(1,(e.clientY-r.top-18)/(r.height-36)))*2);}photoSlider.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();photoDrag=true;photoSlider.focus({preventScroll:true});photoSlider.setPointerCapture(e.pointerId);chooseHero(photoIndex(e));};photoSlider.onpointermove=e=>{if(photoDrag&&photoIndex(e)!==heroFront)chooseHero(photoIndex(e));};photoSlider.onpointerup=photoSlider.onpointercancel=()=>photoDrag=false;photoSlider.onkeydown=e=>{if(['ArrowUp','ArrowLeft','ArrowDown','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();chooseHero(e.key==='Home'?0:e.key==='End'?2:heroFront+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1));}};
document.querySelectorAll('[data-work-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-work-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-work-kind]').forEach(c=>c.hidden=b.dataset.workFilter==='video'&&c.dataset.workKind!=='video');});document.querySelectorAll('[data-work-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-work-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('.work-grid').classList.toggle('view-list',b.dataset.workView==='list');});document.querySelectorAll('[data-work-video]').forEach(b=>b.onclick=()=>{detail={slug:b.dataset.workVideo};window.selectPaper(0);document.querySelector('.video-load')?.click();});const legacyWorkPreview=document.querySelector('[data-work-preview]');if(legacyWorkPreview)legacyWorkPreview.onclick=()=>{const dialog=document.querySelector('.explore-dialog');exploreState='work-preview';exploreBody.innerHTML='<h2>'+tr('封面图像试样','Cover image study')+'</h2><div class="atlas-photo photo-ocean"></div><p>'+tr('CC0 公共纸卡素材，用于封面展示试样，非个人作品。','CC0 public postcard asset used as a cover study, not personal work.')+'</p>';explore.showModal();};document.querySelectorAll('[data-note-page]').forEach(b=>b.onclick=()=>{learningPage=+b.dataset.notePage;updateLearning();syncHero();});const oldNext=document.querySelector('.learning-next').onclick,oldPrev=document.querySelector('.learning-prev').onclick;document.querySelector('.learning-next').onclick=()=>{oldNext();syncHero();};document.querySelector('.learning-prev').onclick=()=>{oldPrev();syncHero();};const controlsLanguage=document.querySelector('.language').onclick;document.querySelector('.language').onclick=()=>{controlsLanguage();syncHero();};syncHero();
