document.querySelectorAll('[data-reading-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-reading-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('.writing-shelf').classList.toggle('index-view',b.dataset.readingView==='list');settleIn([...document.querySelectorAll('.writing-list button')]);});
document.querySelectorAll('[data-repo-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-repo-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const folders=[...document.querySelectorAll('[data-repo-kind]')];folders.forEach(x=>x.hidden=b.dataset.repoFilter!=='all'&&x.dataset.repoKind!==b.dataset.repoFilter);settleIn(folders.filter(x=>!x.hidden));});
