const navLens=document.querySelector('.nav-lens'),navRoot=document.querySelector('.nav-links');
new MutationObserver(()=>document.querySelectorAll('.nav [data-open]').forEach(b=>b.setAttribute('aria-expanded',String(index===+b.dataset.open)))).observe(document.querySelector('.look'),{attributes:true,attributeFilter:['class']});
const photoStrip=document.querySelector('.photo-strip');let albumPosition=0;
function moveAlbum(delta){albumPosition=Math.max(0,Math.min(2,albumPosition+delta));const target=photoStrip.children[albumPosition];photoStrip.scrollTo({left:target.offsetLeft-photoStrip.children[0].offsetLeft,behavior:reduced()?'instant':'smooth'});}
document.querySelector('.album-prev').onclick=()=>moveAlbum(-1);document.querySelector('.album-next').onclick=()=>moveAlbum(1);
explore.addEventListener('close',()=>{document.querySelector('[data-explore="'+exploreState+'"]')?.focus({preventScroll:true});});function paintProgress(){seek.style.setProperty('--played',(Number(seek.value)/24*100)+'%');requestAnimationFrame(paintProgress);}paintProgress();
const designTablist=document.querySelector('.design-tabs');designTablist.setAttribute('role','tablist');designTablist.setAttribute('aria-label',tr('设计试样分类','Design study categories'));const designTabs=[...designTablist.children],designPanel=document.querySelector('.design-preview');designPanel.id='design-study-panel';designPanel.setAttribute('role','tabpanel');function syncDesignTabs(){designTabs.forEach((b,i)=>{b.id='design-tab-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls',designPanel.id);const selected=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected)designPanel.setAttribute('aria-labelledby',b.id);});}designTabs.forEach((b,i)=>{b.addEventListener('click',syncDesignTabs);b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;designTabs[next].focus();designTabs[next].click();});});syncDesignTabs();
function syncAlbumControls(){const first=photoStrip.children[0];let nearest=0,distance=Infinity;[...photoStrip.children].forEach((e,i)=>{const d=Math.abs(photoStrip.scrollLeft-(e.offsetLeft-first.offsetLeft));if(d<distance){distance=d;nearest=i;}});albumPosition=nearest;document.querySelector('.album-prev').disabled=nearest===0;document.querySelector('.album-next').disabled=nearest===2;}
photoStrip.addEventListener('scroll',syncAlbumControls,{passive:true});syncAlbumControls();document.querySelectorAll('.nav [data-open]').forEach(b=>b.setAttribute('aria-expanded','false'));

// The same three marks stay available inside the expanded card header on every screen.
(()=>{const holder=document.querySelector('.photo-ruler'),home=document.querySelector('.look'),head=document.querySelector('.reader-head'),marks=[...photoSlider.querySelectorAll('.photo-tick')],original=marks.map(e=>e.style.cssText);function place(){const opened=home.classList.contains('open');const destination=opened?head:home;if(holder.parentElement!==destination)destination.insertBefore(holder,opened?head.querySelector('.close'):home.querySelector('.hint'));photoSlider.setAttribute('aria-orientation',opened?'horizontal':'vertical');marks.forEach((e,i)=>e.style.cssText=opened?'top:22px;left:'+(22+i*44)+'px;bottom:auto;transform:translateX(-50%)':original[i]);}new MutationObserver(place).observe(home,{attributes:true,attributeFilter:['class']});place();})();
